void Ent::updateArrow(double dt) { life -= dt; if (life <= 0) { dead = true; return; } x += vx * dt; y += vy * dt;
  if (g->world.solid((int)std::floor(x / TS), (int)std::floor((y + zz) / TS))) { dead = true; g->fx.burst(x, y + zz, 3, {C3(0xc8a070)}, 15, 50, 20, 60, 160, 0.4, 0.8, zz); return; }
  Ent* hit = g->nearest(x, y + zz, 9, [&](Ent* e) { return e != src.get() && !e->dead && e->kind != E_DROP && e->kind != E_ARROW && g->hostile(src.get(), e); }); if (hit) { hit->hurt(dmg, src.get(), 70); dead = true; snd("hit", g->vol(x, y), 1, g->pan(x)); } }
/* ---------------- player ---------------- */
